/* =============================================================
 *  VUKANG OS - kernel/splash.c : animated boot splash
 *
 *  Layers (assets/splash/ *.vkimg files, generated by tools/mksplash.py):
 *    emblem   - the glowing "V", zooms in and "breathes"
 *    wordmark - "VUKANG", slides up and fades in
 *  Drawn in code:
 *    rising light particles, a glowing progress bar that follows the
 *    real boot stages, a light sweep across the logo, and a fade-out.
 *
 *  Everything is composed in a RAM back buffer and copied to the
 *  framebuffer once per frame, so there is no flicker. Time comes from
 *  the PIT (timer_ticks), so the animation runs at the same speed on
 *  every machine; slow machines simply draw fewer frames.
 *  Without a framebuffer a small text-mode version is shown instead.
 * ============================================================= */
#include "splash.h"
#include "fb.h"
#include "vga.h"
#include "arch.h"
#include "mm.h"
#include "drivers.h"
#include "kernel.h"
#include "string.h"
#include "console.h"

extern const uint8_t asset_emblem[], asset_wordmark[];
typedef struct { int w, h; const uint8_t *px; } img_t;

#define NP 56                                   /* particles */
typedef struct { int x, y, vx, vy, life, max; } particle_t;

static struct {
    bool on, text, skip;
    uint32_t t0, last, step_t, label_t;
    int prog, target;                           /* 0..1000 */
    const char *label;
    img_t em, wm;
    uint32_t frames;
    uint32_t *buf; int bw, bh, bx, by;          /* back buffer and its screen position */
    int cx, ecy, wcy, bary, laby, very;         /* layout, in buffer coordinates */
    int fade;                                   /* 256 = fully visible */
    int shine;                                  /* sweep position, -100000 = off */
    particle_t p[NP];
    uint32_t rng;
} S;

/* ---------- small helpers ---------- */
static uint32_t now(void) { return (timer_ticks() - S.t0) * (1000 / timer_hz()); }
static int clamp(int v, int lo, int hi) { return v < lo ? lo : v > hi ? hi : v; }
static int ease_out(int p) { int q = 256 - clamp(p, 0, 256); return 256 - q * q / 256 * q / 256; }
static int phase(uint32_t t, int start, int len) { return clamp(((int)t - start) * 256 / len, 0, 256); }
static int rnd(int n) { S.rng = S.rng * 1103515245u + 12345u; return (int)((S.rng >> 16) % (uint32_t)n); }
/* sine of deg (any int), result -256..256 (Bhaskara I approximation) */
static int isin(int deg) {
    deg %= 360; if (deg < 0) deg += 360;
    int s = 1; if (deg >= 180) { deg -= 180; s = -1; }
    int n = 4 * deg * (180 - deg);
    return s * n * 256 / (40500 - deg * (180 - deg));
}
static inline uint32_t rgb_scale(uint32_t c, int a) {
    int r = ((c >> 16) & 255) * a >> 8, g = ((c >> 8) & 255) * a >> 8, b = (c & 255) * a >> 8;
    return (uint32_t)(clamp(r, 0, 255) << 16 | clamp(g, 0, 255) << 8 | clamp(b, 0, 255));
}
static inline void add_px(int x, int y, uint32_t c) {
    if (x < 0 || y < 0 || x >= S.bw || y >= S.bh) return;
    uint32_t *d = &S.buf[y * S.bw + x], o = *d;
    int r = ((o >> 16) & 255) + ((c >> 16) & 255), g = ((o >> 8) & 255) + ((c >> 8) & 255), b = (o & 255) + (c & 255);
    *d = (uint32_t)((r > 255 ? 255 : r) << 16 | (g > 255 ? 255 : g) << 8 | (b > 255 ? 255 : b));
}
static bool load(img_t *im, const uint8_t *a) {
    if (a[0] != 'V' || a[1] != 'K' || a[2] != 'I' || a[3] != 'M') return false;
    im->w = a[4] | a[5] << 8; im->h = a[6] | a[7] << 8; im->px = a + 8;
    return im->w > 0 && im->h > 0 && im->w <= 1024 && im->h <= 1024;
}

/* ---------- layers ---------- */
/* Draw an image centred at (cx, cy) with scale (256 = 1:1), brightness a
 * (256 = original) and the light sweep. Black source pixels are transparent. */
static void draw_img(const img_t *im, int cx, int cy, int scale, int a) {
    static int16_t colmap[1100];
    int dw = im->w * scale >> 8, dh = im->h * scale >> 8;
    if (dw <= 0 || dh <= 0 || dw > 1100 || a <= 0) return;
    int x0 = cx - dw / 2, y0 = cy - dh / 2;
    for (int x = 0; x < dw; x++) colmap[x] = (int16_t)(x * im->w / dw);
    for (int y = 0; y < dh; y++) {
        int yy = y0 + y;
        if (yy < 0 || yy >= S.bh) continue;
        const uint8_t *src = im->px + (y * im->h / dh) * im->w * 3;
        uint32_t *d = S.buf + yy * S.bw;
        int sh0 = S.shine - yy * 2 / 5;                    /* diagonal band */
        for (int x = 0; x < dw; x++) {
            int xx = x0 + x;
            if (xx < 0 || xx >= S.bw) continue;
            const uint8_t *p = src + colmap[x] * 3;
            int r = p[0], g = p[1], b = p[2];
            if (!(r | g | b)) continue;
            r = r * a >> 8; g = g * a >> 8; b = b * a >> 8;
            int dist = xx - sh0; if (dist < 0) dist = -dist;
            if (dist < 64) {                                 /* light sweep */
                int m = r > g ? (r > b ? r : b) : (g > b ? g : b);
                int k = (64 - dist) * (64 - dist) * m / (64 * 48) * a >> 8;
                r += k; g += k; b += k;
            }
            d[xx] = (uint32_t)((r > 255 ? 255 : r) << 16 | (g > 255 ? 255 : g) << 8 | (b > 255 ? 255 : b));
        }
    }
}

static void spawn(particle_t *q, bool anywhere) {
    q->x = (S.cx - S.em.w / 2 + 50 + rnd(S.em.w - 100)) << 8;
    q->y = (S.ecy - S.em.h / 6 + rnd(S.em.h / 2)) << 8;
    q->vx = rnd(31) - 15;                               /* 1/256 px per ms */
    q->vy = -(14 + rnd(40));
    q->max = 900 + rnd(1300);
    q->life = anywhere ? rnd(q->max) : 0;
}
static void particles(int dt, int a) {
    for (int i = 0; i < NP; i++) {
        particle_t *q = &S.p[i];
        q->x += q->vx * dt; q->y += q->vy * dt; q->life += dt;
        if (q->life >= q->max) spawn(q, false);
        int l = q->life, f = l < 250 ? l * 256 / 250 : (q->max - l) * 256 / (q->max - 250);
        f = f * a >> 8;
        if (f <= 0) continue;
        int x = q->x >> 8, y = q->y >> 8;
        uint32_t core = rgb_scale(0x7FF0FF, f), halo = rgb_scale(0x1A7FA0, f);
        add_px(x, y, core); add_px(x + 1, y, core); add_px(x, y + 1, core); add_px(x + 1, y + 1, core);
        add_px(x - 1, y, halo); add_px(x + 2, y, halo); add_px(x, y - 1, halo); add_px(x + 1, y + 2, halo);
    }
}

static void draw_bar(uint32_t t, int a) {
    const int W = 380, H = 6;
    int x0 = S.cx - W / 2, fill = W * S.prog / 1000;
    int sheen = (int)(t / 3 % (uint32_t)(W + 160)) - 80;   /* moving highlight */
    for (int r = -3; r < H + 3; r++) {
        int y = S.bary + r;
        if (y < 0 || y >= S.bh) continue;
        uint32_t *d = S.buf + y * S.bw;
        for (int x = 0; x < W; x++) {
            int xx = x0 + x;
            if (xx < 0 || xx >= S.bw) continue;
            bool inside = r >= 0 && r < H;
            bool corner = (x == 0 || x == W - 1) && (r == 0 || r == H - 1);
            if (x < fill) {
                int k = x * 256 / W;                        /* blue -> cyan gradient */
                int cr = 0x0A + ((0x3F - 0x0A) * k >> 8), cg = 0x6C + ((0xE0 - 0x6C) * k >> 8), cb = 0xFF - ((0xFF - 0xF0) * k >> 8);
                int s = x - sheen; if (s < 0) s = -s;
                int boost = s < 40 ? (40 - s) * 3 : 0;
                int lvl = inside ? (corner ? 150 : 256) : (r == -1 || r == H) ? 80 : (r == -2 || r == H + 1) ? 36 : 14;
                uint32_t c = (uint32_t)(clamp(cr + boost, 0, 255) << 16 | clamp(cg + boost, 0, 255) << 8 | clamp(cb + boost / 2, 0, 255));
                d[xx] = rgb_scale(c, lvl * a >> 8);
            } else if (inside && !corner) {
                d[xx] = rgb_scale(0x12303A, a);
            }
        }
    }
    if (fill > 0) {                                         /* glowing head */
        int pulse = 200 + (isin((int)t / 3) >> 3);
        for (int dy = -7; dy <= 7 + H; dy++)
            for (int dx = -9; dx <= 3; dx++) {
                int ddy = dy < 0 ? -dy : dy > H ? dy - H : 0, dist = ddy * ddy + dx * dx;
                if (dist > 64) continue;
                add_px(x0 + fill + dx, S.bary + dy, rgb_scale(0x6FF6FF, (64 - dist) * pulse / 64 * a >> 9));
            }
    }
}

static void draw_text(const char *s, int cx, int y, uint32_t rgb, int a) {
    if (a <= 0) return;
    int fw = vga_font_w(), fh = vga_font_h(), bpr = vga_font_bpr(), n = (int)strlen(s);
    uint32_t c = rgb_scale(rgb, a);
    int x = cx - n * fw / 2;
    for (; *s; s++, x += fw) {
        const uint8_t *g = vga_glyph((uint8_t)*s);
        for (int r = 0; r < fh; r++, g += bpr) {
            uint32_t bits = bpr == 1 ? (uint32_t)g[0] << 8 : ((uint32_t)g[0] << 8) | g[1];
            int yy = y + r;
            if (yy < 0 || yy >= S.bh) continue;
            for (int k = 0; k < fw; k++)
                if ((bits & (0x8000u >> k)) && x + k >= 0 && x + k < S.bw) S.buf[yy * S.bw + x + k] = c;
        }
    }
}

/* ---------- one frame ---------- */
static void frame(void) {
    uint32_t t = now();
    int dt = clamp((int)(t - S.last), 0, 100); S.last = t;
    if (keyboard_getc_nonblock() >= 0) S.skip = true;
    if (S.prog < S.target) S.prog = clamp(S.prog + dt * 1000 / 650 + 1, 0, S.target);

    int pe = ease_out(phase(t, 0, 850));                    /* emblem zoom-in */
    int pw = ease_out(phase(t, 420, 620));                  /* wordmark slide-up */
    int pb = phase(t, 700, 400);                            /* bar fade-in */
    int g = S.fade;
    int breathe = t > 900 ? isin((int)(t - 900) * 360 / 2400) / 14 : 0;   /* slow glow pulse */

    if (S.text) {                                           /* ---- text-mode fallback ---- */
        volatile uint16_t *v = (uint16_t *)0xB8000;
        const char *title = "V U K A N G   O S";
        int n = (int)strlen(title), x0 = 40 - n / 2;
        for (int i = 0; i < 80 * 25; i++) v[i] = 0x0020;
        uint8_t tc = pe > 128 ? 0x0B : 0x03;
        for (int i = 0; i < n; i++) v[9 * 80 + x0 + i] = (uint16_t)(uint8_t)title[i] | (tc << 8);
        int filled = 40 * S.prog / 1000, head = (int)(t / 60) % 40;
        for (int i = 0; i < 40; i++)
            v[12 * 80 + 20 + i] = i < filled ? (uint16_t)(0xDB | ((i == head ? 0x0F : 0x0B) << 8)) : (uint16_t)(0xB0 | (0x08 << 8));
        if (S.label) { int l = (int)strlen(S.label); for (int i = 0; i < l && i < 78; i++) v[14 * 80 + 40 - l / 2 + i] = (uint16_t)(uint8_t)S.label[i] | (0x07 << 8); }
    } else {                                                /* ---- graphics ---- */
        uint32_t *d = S.buf; for (int i = S.bw * S.bh; i; i--) *d++ = 0;
        int zoom = 208 + (48 * pe >> 8) + ((256 - g) >> 4);      /* 0.81 -> 1.0, grows a bit on fade-out */
        draw_img(&S.em, S.cx, S.ecy, zoom, (pe * (256 + breathe) >> 8) * g >> 8);
        draw_img(&S.wm, S.cx, S.wcy + (28 * (256 - pw) >> 8), 256, pw * g >> 8);
        particles(dt, pe * g >> 8);
        draw_bar(t, pb * g >> 8);
        if (S.label) draw_text(S.label, S.cx, S.laby, 0xC4D6E2, phase(t, (int)S.label_t, 200) * pb * g >> 16);
        static char ver[96];
        if (!ver[0]) ksnprintf(ver, sizeof ver, "v%s \"%s\"  -  Made in Tanzania", VUKANG_VERSION, VUKANG_CODENAME);
        draw_text(ver, S.cx, S.very, 0x46576A, pb * g >> 8);
        for (int y = 0; y < S.bh; y++) fb_write_row(S.bx, S.by + y, S.buf + y * S.bw, S.bw);
    }
    S.frames++;
    uint32_t tk = timer_ticks();                            /* wait for the next tick */
    while (timer_ticks() == tk) __asm__ volatile("hlt");
}

static void run_until(uint32_t ms) { while (S.on && !S.skip && now() < ms) frame(); }

/* ---------- public API ---------- */
bool splash_active(void) { return S.on; }

void splash_begin(void) {
    memset(&S, 0, sizeof S);
    S.rng = 0x5EED1234u ^ timer_ticks();
    S.fade = 256; S.shine = -100000;
    if (vga_is_graphics()) {
        if (!load(&S.em, asset_emblem) || !load(&S.wm, asset_wordmark)) { vga_hold(false); return; }
        int fh = vga_font_h();
        int total = S.em.h + 6 + S.wm.h + 46 + 6 + 22 + fh + 10 + fh;
        S.bw = clamp(S.em.w + 160, 400, (int)fb.width);
        S.bh = clamp(total + 70, 200, (int)fb.height);
        S.bx = ((int)fb.width - S.bw) / 2;
        S.by = clamp(((int)fb.height - S.bh) / 2 - 10, 0, (int)fb.height - S.bh);
        S.buf = kmalloc((uint32_t)S.bw * S.bh * 4);
        if (!S.buf) { vga_hold(false); return; }            /* no memory: boot without animation */
        S.cx = S.bw / 2;
        int top = 40;
        S.ecy  = top + S.em.h / 2;
        S.wcy  = top + S.em.h + 6 + S.wm.h / 2;
        S.bary = top + S.em.h + 6 + S.wm.h + 46;
        S.laby = S.bary + 6 + 22;
        S.very = S.laby + fh + 10;
        for (int i = 0; i < NP; i++) spawn(&S.p[i], true);
        fb_fill(0, 0, fb.width, fb.height, 0);
    } else {
        S.text = true;
    }
    S.on = true;
    vga_hold(true);                                          /* console keeps logging silently */
    S.t0 = timer_ticks(); S.last = 0;
    S.label = "Starting kernel"; S.label_t = 0;
    S.target = 300;
    run_until(S.text ? 500 : 1150);
}

void splash_step(int percent, const char *label) {
    if (!S.on) return;
    S.target = clamp(percent * 10, S.target, 1000);
    if (label && label != S.label) { S.label = label; S.label_t = now(); }
    uint32_t start = now();
    while (S.on && !S.skip && (S.prog < S.target || now() < start + 160)) frame();
}

static void finish(void) {
    if (S.buf) { kfree(S.buf); S.buf = 0; }
    if (!S.text && fb.present) fb_fill(0, 0, fb.width, fb.height, 0);
    S.on = false;
    vga_hold(false);                                         /* repaint the console */
    uint32_t ms = now();
    klog("splash", "boot animation: %u frames in %u ms (%u fps)%s", S.frames, ms, ms ? S.frames * 1000 / ms : 0, S.skip ? ", skipped" : "");
}

void splash_end(void) {
    if (!S.on) return;
    if (!S.skip) {
        splash_step(100, "Karibu");
        uint32_t s = now();
        if (!S.text)                                         /* light sweep over the logo */
            while (!S.skip && now() < s + 900) { S.shine = -140 + (int)(now() - s) * (S.bw + 320) / 900; frame(); }
        S.shine = -100000;
        run_until(now() + 200);
    }
    uint32_t s = now(), len = S.skip ? 180 : 420;              /* fade out */
    while (now() < s + len) { S.fade = 256 - (int)(now() - s) * 256 / (int)len; frame(); }
    finish();
}

void splash_abort(void) { S.on = false; vga_hold(false); }   /* also releases an early hold */
